import { ErrorRequestHandler } from 'express';
import { ConflictError, NotFoundError, ValidationError } from '../../../domain/errors/DomainError';
import { RequestValidationError } from '../RequestValidationError';

function statusFor(error: unknown): number {
  if (error instanceof RequestValidationError || error instanceof ValidationError) {
    return 400;
  }
  if (error instanceof NotFoundError) {
    return 404;
  }
  if (error instanceof ConflictError) {
    return 409;
  }
  // Malformed JSON bodies are reported by express.json() as SyntaxError with a status.
  if (error instanceof SyntaxError && 'status' in error && error.status === 400) {
    return 400;
  }
  return 500;
}

export const errorHandler: ErrorRequestHandler = (error: unknown, _req, res, _next) => {
  const status = statusFor(error);
  if (status === 500) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error' });
    return;
  }
  const message = error instanceof Error ? error.message : 'Bad request';
  res.status(status).json({ error: message });
};

=====SOURCE-END=====

